def band_fill(test_grid):
    h = len(test_grid)
    w = len(test_grid[0])
    bands_per_dim = 4

    # Check which horizontal bands have content
    h_bands = []
    band_size_h = h // bands_per_dim
    for b in range(bands_per_dim):
        band_sum = 0
        for r in range(b*band_size_h, min((b+1)*band_size_h, h)):
            for c in range(w):
                band_sum += test_grid[r][c]
        if band_sum > 0:
            h_bands.append(b)

    # Check which vertical bands have content
    v_bands = []
    band_size_v = w // bands_per_dim
    for b in range(bands_per_dim):
        band_sum = 0
        for r in range(h):
            for c in range(b*band_size_v, min((b+1)*band_size_v, w)):
                band_sum += test_grid[r][c]
        if band_sum > 0:
            v_bands.append(b)

    print(f"Horizontal bands with content: {h_bands}")
    print(f"Vertical bands with content: {v_bands}")

    # Output = cross-product of h_bands x v_bands
    output = [[0]*bands_per_dim for _ in range(bands_per_dim)]
    for h_b in h_bands:
        for v_b in v_bands:
            output[h_b][v_b] = 1

    return output

result = band_fill(test_grid)
print("\nBand fill result:")
for row in result:
    print(row)

